    }

    // Iterar sobre todas las filas de datos (tbody tr)
    const rows = document.querySelector('#spreadsheet tbody').querySelectorAll('tr');

    rows.forEach(row => {
        // Encontrar la celda correspondiente en esta fila y columna
        // El índice del TD es relativo al <tbody>, por lo que usamos nth-child(N+1) donde N=selectedColIndex
        const cellToClear = row.querySelector(`td:nth-child(${selectedColIndex + 2})`);
        if (cellToClear) {
            // Limpiar contenido y resetear color de fondo
            cellToClear.innerHTML = '';
            cellToClear.textContent = '';
            cellToClear.style.backgroundColor = ''; 
        }
    });

    console.log("Contenido de la columna " + colHeader.textContent + " borrado exitosamente.");
}
