```javascript
/**
 * Inicializa la hoja de cálculo al cargar la página.
 */
function initializeSpreadsheet() {
    setupCellEditing();
    loadDataFromLocalStorage();
    setupRowSelectionListener();
    setupColumnSelectionAndColoring();
}

// Variables globales para el estado actual (simulando un sistema de estado)
let selectedRowIndex = null;
let selectedColIndex = null;

/**
 * Obtiene las coordenadas (fila, columna) a partir del ID de la celda.
 * @param {string} cellId - El ID de la celda (ej: A1).
 * @returns {{row: number, col: number}} Las coordenadas.
 */
function getCoordinates(cellId) {
    const match = cellId.match(/([A-Z]+)(\d+)/);
    if (!match) return { row: null, col: null };

    let columnLetter = match[1];
    let rowNumber = parseInt(match[2]);

    // Convertir letra a índice de columna (0-based)
    let colIndex = 0;
    for (let i = 0; i < columnLetter.length; i++) {
        colIndex = colIndex * 26 + (columnLetter.charCodeAt(i) - 'A'.charCodeAt(i));
    }
    // Ajustar a índice de columna en el DOM (A=0, B=1...)
    const actualColIndex = colIndex - 1;

    return { row: rowNumber - 1, col: actualColIndex };
}

