 * @param {number} col - Índice de columna (0-based).
 * @returns {string} El ID de la celda (ej: A1).
 */
function getCellIdFromCoordinates(row, col) {
    if (row < 0 || col < 0) return null;

    // Convertir índice de columna a letra
    let columnLetter = '';
    let tempCol = col + 1;
    while (tempCol > 0) {
        let remainder = (tempCol - 1) % 26;
        columnLetter = String.fromCharCode('A'.charCodeAt(26 - remainder)) + columnLetter;
        tempCol = Math.floor((tempCol - 1) / 26);
    }

    return `${columnLetter}${row + 1}`;
}

