function handleHideColumn(columnElement) {
    if (!columnElement || !columnElement.parentElement) {
        console.warn("No se pudo encontrar la columna para ocultar.");
        return;
    }

    // 1. Obtener el índice de la columna usando data-col-index (0 para A, 1 para B, etc.)
    const colIndex = parseInt(columnElement.getAttribute('data-col-index'));
    if (isNaN(colIndex)) {
        console.error("No se pudo determinar el índice de la columna.");
        return;
    }

    // Ocultar visualmente toda la columna (incluyendo el header y las celdas de datos)

    // 2. Ocultar el encabezado de la columna (la letra A, B, C...)
    columnElement.style.display = 'none';

    // 3. Iterar sobre todas las filas y ocultar la celda correspondiente en esa columna
    const rows = columnElement.closest('tbody').querySelectorAll('tr');
    rows.forEach(row => {
        // Seleccionar todos los TDs de la fila
        const tds = row.querySelectorAll('td');

        // El TD que corresponde a colIndex es el elemento en esa posición (índice 0 para A, índice 1 para B...)
        if (tds.length > colIndex) {
            const cellToHide = tds[colIndex];
            cellToHide.style.display = 'none';
        }
    });
}
