// Global variables for state management
let selectedRowIndex = -1;
let selectedColIndex = -1;

/**
 * @param {HTMLElement} cellElement El elemento TD de la celda seleccionada.
 */
function setupCellEditing(cellElement) {
    if (!cellElement) return;

    // Limpiar cualquier listener previo para evitar duplicados
    cellElement.onblur = null; 
    cellElement.onkeydown = null;

    cellElement.onblur = function() {
        // Cuando el foco sale de la celda, actualizar estado y guardar datos
        saveCellData(this);
        updateSelectionState();
    };

    cellElement.onkeydown = function(e) {
        if (e.key === 'Enter') {
            e.preventDefault(); // Prevenir salto de línea por defecto
            // Simular pérdida de foco para guardar datos y actualizar estado
            this.blur(); 
        } else if (e.key === 'Delete' || e.key === 'Backspace') {
            // Manejar borrado de contenido al presionar Delete/Backspace
            if (!e.altKey && !e.ctrlKey) { // Solo si no es un atajo de teclado global
                const cell = this;
                cell.innerHTML = '';
                cell.textContent = '';
                saveCellData(cell);
                updateSelectionState();
            }
        }
    };
}

/**
 * Obtiene las coordenadas (fila, columna) a partir del elemento TD.
 * @param {HTMLElement} cellElement El elemento TD.
 * @returns {{row: number, col: number}|null} Las coordenadas o null si no se encuentra.
 */
function getCoordinates(cellElement) {
    if (!cellElement || !cellElement.dataset.cell) return null;

    const cellId = cellElement.dataset.cell; // Ej: A1, B20
    const match = cellId.match(/([A-Z]+)(\d+)/);

    if (match) {
        let colStr = match[1];
        let rowNum = parseInt(match[2]);

        // Convertir letras a índice de columna (A=0, B=1, ...)
        let colIndex = 0;
        for (let i = 0; i < colStr.length; i++) {
            colIndex = colIndex * 26 + (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
            colIndex--; // Ajustar a índice base 0
        }

        // Las filas en el DOM son 1-based, pero los índices de datos son 0-based.
        return { row: rowNum - 1, col: colIndex };
    }
    return null;
}

/**
 * Obtiene el ID de la celda a partir de coordenadas (fila, columna).
 * @param {number} row Índice de fila (0-based).
 * @param {number} col Índice de columna (0-based).
 * @returns {string} El ID de la celda (Ej: A1, B20).
 */
function getCellIdFromCoordinates(row, col) {
    if (isNaN(row) || isNaN(col)) return null;

    // Convertir índice de columna a letra (0=A, 1=B, ...)
    let colStr = '';
    let tempCol = col;
    while (tempCol >= 0) {
        colStr = String.fromCharCode((tempCol % 26) + 65) + colStr;
        tempCol = Math.floor(tempCol / 26) - 1;
    }

    return `${colStr}${row + 1}`;
}

/**
 * Calcula y actualiza el estado de la celda (coordenadas, contenido).
 * @param {HTMLElement} cellElement El elemento TD.
 */
function calculateCell(cellElement) {
    const coords = getCoordinates(cellElement);
    if (!coords) return null;

    // Actualizar índices globales si es necesario
    selectedRowIndex = coords.row;
    selectedColIndex = coords.col;

    return { row: coords.row, col: coords.col };
}

