 */
function loadDataFromLocalStorage() {
    const data = JSON.parse(localStorage.getItem('spreadsheetData')) || {};
    if (!data) return;

    // Limpiar contenido existente antes de cargar
    document.querySelectorAll('#spreadsheet td').forEach(cell => {
        cell.innerHTML = '';
        cell.textContent = '';
        cell.style.backgroundColor = ''; // Reset background color
    });

    for (const cellId in data) {
        if (data[cellId] !== null && data[cellId] !== undefined) {
            const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
            if (cellElement) {
                // Restaurar contenido y estilos
                cellElement.textContent = data[cellId].content;
                if (data[cellId].color) {
                    cellElement.style.backgroundColor = data[cellId].color;
                }
            }
        }
    }
}

/**
 * Guarda el contenido y estilos de la celda activa en LocalStorage.
 * @param {HTMLElement} cellElement El elemento TD que ha perdido foco.
 */
function saveCellData(cellElement) {
    if (!cellElement || !cellElement.dataset.cell) return;

    const cellId = cellElement.dataset.cell;
    let data = JSON.parse(localStorage.getItem('spreadsheetData')) || {};

    data[cellId] = {
        content: cellElement.textContent,
        color: cellElement.style.backgroundColor || '',
    };

    localStorage.setItem('spreadsheetData', JSON.stringify(data));
}


